CREATE OR REPLACE FUNCTION InsertOrUpdateAccount(
    p_account_id BIGINT,
    p_district_id BIGINT,
    p_frequency TEXT,
    p_date DATE
)
RETURNS VOID AS
$$
BEGIN
    IF EXISTS (SELECT 1 FROM account WHERE account_id = p_account_id) THEN
        UPDATE account
        SET frequency = p_frequency, date = p_date
        WHERE account_id = p_account_id;
    ELSE
        INSERT INTO account (account_id, district_id, frequency, date)
        VALUES (p_account_id, p_district_id, p_frequency, p_date);
    END IF;
END;
$$ LANGUAGE plpgsql;

